    },
    "message": {
      "type": "string",
      "description": "The follow-up instruction or question."
    }
  },
  "required": [
    "id",
    "message"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The failed subagent id."
    },
    "message": {
      "type": "string",
